{"command": "cd /tmp && python3 - <<'PY'
import json,urllib.request,urllib.error,time

SVC=open('/tmp/svc.key').read().strip()
URL=open('/tmp/sb.url').read().strip()
OWNER=open('/tmp/owner.email').read().strip()

def req(method,url,headers,body=None,timeout=30):
    data=json.dumps(body).encode() if body is not None else None
    r=urllib.request.Request(url,data=data,headers=headers,method=method)
    try:
        with urllib.request.urlopen(r,timeout=timeout) as resp:
            return resp.status, resp.read().decode()
    except urllib.error.HTTPError as e:
        return e.code, e.read().decode()
    except Exception as e:
        return 0, f'TRANSPORT:{type(e).__name__}:{e}'

adminH={'apikey':SVC,'Authorization':'Bearer '+SVC,'Content-Type':'application/json'}

print("=== raw admin call, status ALWAYS printed ===")
s,b=req('GET',f'{URL}/auth/v1/admin/users?per_page=200&page=1',adminH)
print("  http =",s)
print("  body_head =",b[:200])

if s!=200:
    print("\n  >>> The admin lookup FAILED. 'account missing' was NOT proven.")
else:
    total=[]
    page=1
    while True:
        s2,b2=req('GET',f'{URL}/auth/v1/admin/users?per_page=200&page={page}',adminH)
        if s2!=200: break
        us=json.loads(b2).get('users',[])
        if not us: break
        total+=us
        page+=1
        if page>15: break
    print(f"  users_fetched = {len(total)} across {page-1} page(s)")
    hit=[u for u in total if (u.get('email') or '').lower()==OWNER.lower()]
    print("  owner_match   =", len(hit))
    for u in hit:
        print("   exists YES | confirmed", bool(u.get('email_confirmed_at')),
              "| banned", u.get('banned_until') or 'none',
              "| providers", [i.get('provider') for i in (u.get('identities') or [])],
              "| last_sign_in", u.get('last_sign_in_at') or 'never')
    if not hit:
        doms={}
        for u in total:
            e=(u.get('email') or '')
            if '@' in e: doms['@'+e.split('@')[1]]=doms.get('@'+e.split('@')[1],0)+1
        print("  no exact match. domains present:", dict(sorted(doms.items(),key=lambda x:-x[1])[:6]))
